using System;

class Program
{
    static void Main()
    {
        int a = 42;
        System.Int32 b = 42;          // identical to int
        string s = "hi";

        Console.WriteLine(a.GetType());            // System.Int32
        Console.WriteLine(b.GetType() == a.GetType()); // True
        Console.WriteLine(s.GetType().IsValueType);    // False (reference type)
        Console.WriteLine(Environment.Version);        // runtime version, e.g. 8.0.x
    }
}

using System;

struct PointS { public int X; }
class PointC { public int X; }

class Program
{
    static void Main()
    {
        PointS s1 = new PointS { X = 1 };
        PointS s2 = s1;   // copies the data
        s2.X = 99;
        Console.WriteLine(s1.X); // 1

        PointC c1 = new PointC { X = 1 };
        PointC c2 = c1;   // copies the reference
        c2.X = 99;
        Console.WriteLine(c1.X); // 99

        int n = 10;
        object boxed = n; // boxing
        n = 20;
        Console.WriteLine(boxed); // 10
        int back = (int)boxed;    // unboxing
        Console.WriteLine(back + n); // 30
    }
}

using System;
using System.Text;

class Program
{
    static string Slow(int n)
    {
        string s = "";
        for (int i = 0; i < n; i++) s += i + ",";   // n new strings
        return s;
    }

    static string Fast(int n)
    {
        var sb = new StringBuilder(n * 4);
        for (int i = 0; i < n; i++) sb.Append(i).Append(',');
        return sb.ToString();                          // one final string
    }

    static void Main()
    {
        Console.WriteLine(Slow(5)); // 0,1,2,3,4,
        Console.WriteLine(Fast(5) == Slow(5)); // True
    }
}

